// ── Load Conversation History ──────────────────────────────
// Reads the session's message history from n8n static data.
// History is keyed by session_id from the URL query parameter.

const staticData = $getWorkflowStaticData('global');
const sessionId  = $('Webhook').item.json.query?.session_id || 'default';
const transcript = $input.first().json.transcript || '';

// Initialise storage
if (!staticData.sessions) staticData.sessions = {};

// Expire sessions inactive for > 30 minutes
const EXPIRE_MS = 30 * 60 * 1000;
const now = Date.now();
for (const [sid, s] of Object.entries(staticData.sessions)) {
  if (now - (s.lastActivity || 0) > EXPIRE_MS) {
    delete staticData.sessions[sid];
  }
}

// Load this session's history (or start fresh)
const history = staticData.sessions[sessionId]?.messages || [];

return [{ json: { session_id: sessionId, transcript, history } }];

