// ── Save Conversation History ──────────────────────────────
// Appends the latest user + assistant turn to static data.
// Trims to last 20 messages (10 turns) to manage context size.

const staticData = $getWorkflowStaticData('global');
const sessionId  = $('Load History').item.json.session_id;
const transcript = $('Load History').item.json.transcript;
const aiReply    = $input.first().json.choices?.[0]?.message?.content || '';

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[sessionId]) {
  staticData.sessions[sessionId] = { messages: [], lastActivity: Date.now() };
}

const session = staticData.sessions[sessionId];

// Add this turn
session.messages.push({ role: 'user',      content: transcript });
session.messages.push({ role: 'assistant', content: aiReply });

// Keep last 20 messages (10 turns)
if (session.messages.length > 20) {
  session.messages = session.messages.slice(-20);
}

session.lastActivity = Date.now();

return [{ json: { text: aiReply, session_id: sessionId, transcript } }];
